172	static uint64_t read_reg64(struct qemu_plugin_register *h)
173	{
174	    if (!h) return 0;
175	    g_autoptr(GByteArray) buf = g_byte_array_new();
176	    int sz = qemu_plugin_read_register(h, buf);
177	    if (sz <= 0) return 0;
178	    uint64_t v = 0;
179	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
180	    return v;
181	}
