183	// Reads up to `dst_max` bytes from a register handle. Returns the byte
184	// count written (0 on failure or NULL handle). Used for vector regs whose
185	// width = vlenb bytes.
186	static size_t read_reg_bytes(struct qemu_plugin_register *h,
187	                             uint8_t *dst, size_t dst_max)
188	{
189	    if (!h || dst_max == 0) return 0;
190	    g_autoptr(GByteArray) buf = g_byte_array_new();
191	    int sz = qemu_plugin_read_register(h, buf);
192	    if (sz <= 0) return 0;
193	    size_t n = (size_t) sz < dst_max ? (size_t) sz : dst_max;
194	    memcpy(dst, buf->data, n);
195	    return n;
196	}
